import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { motion } from 'framer-motion';
import { FaMountain, FaEnvelope, FaLock, FaArrowRight } from 'react-icons/fa';
import './Login.css';

function Login() {
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSendOTP = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!email || !email.includes('@')) {
      setError('Please enter a valid email address');
      setLoading(false);
      return;
    }

    // Simulate OTP sending
    setTimeout(() => {
      alert(`OTP sent to ${email}. For demo, use: 123456`);
      setStep(2);
      setLoading(false);
    }, 1000);
  };

  const handleVerifyOTP = (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (otp === '123456') {
      login(email);
      navigate('/');
    } else {
      setError('Invalid OTP. Please try again.');
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <motion.div
        className="login-background"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 1 }}
      >
        <div className="gradient-overlay"></div>
      </motion.div>

      <motion.div
        className="login-card"
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.2 }}
      >
        <div className="login-header">
          <motion.div
            className="logo-icon"
            animate={{ rotate: [0, 10, -10, 0] }}
            transition={{ duration: 2, repeat: Infinity, repeatDelay: 3 }}
          >
            <FaMountain size={60} color="#2E7D32" />
          </motion.div>
          <h1 className="login-title">AR Smart Tourism</h1>
          <p className="login-subtitle">Nilgiris Heritage & Culture</p>
        </div>

        <div className="login-form">
          {step === 1 ? (
            <motion.form
              onSubmit={handleSendOTP}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.3 }}
            >
              <div className="input-group">
                <FaEnvelope className="input-icon" />
                <input
                  type="email"
                  placeholder="Enter your email ID"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  className="login-input"
                />
              </div>

              {error && <div className="error-message">{error}</div>}

              <motion.button
                type="submit"
                className="login-button"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                disabled={loading}
              >
                {loading ? 'Sending OTP...' : 'Send OTP'} <FaArrowRight />
              </motion.button>
            </motion.form>
          ) : (
            <motion.form
              onSubmit={handleVerifyOTP}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.3 }}
            >
              <p className="otp-message">OTP sent to <strong>{email}</strong></p>

              <div className="input-group">
                <FaLock className="input-icon" />
                <input
                  type="text"
                  placeholder="Enter OTP (123456)"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                  required
                  className="login-input"
                  maxLength="6"
                />
              </div>

              {error && <div className="error-message">{error}</div>}

              <motion.button
                type="submit"
                className="login-button"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                disabled={loading}
              >
                {loading ? 'Verifying...' : 'Verify & Login'} <FaArrowRight />
              </motion.button>

              <button
                type="button"
                className="back-button"
                onClick={() => {
                  setStep(1);
                  setError('');
                  setOtp('');
                }}
              >
                ← Back to Email
              </button>
            </motion.form>
          )}
        </div>

        <div className="login-footer">
          <p>Experience Nilgiris like never before with AR technology</p>
        </div>
      </motion.div>
    </div>
  );
}

export default Login;
